export const catalog_by_category = {
  apple_new,
  apple_cpo,
  samsung,
  samsung_tablets,
  samsung_watches,
  xiaomi,
  motorola,
  apple_accessories,
  mac,
  gaming,
  smart_glasses,
  cameras,
  drones,
  microphones,
  garmin,
  jbl,
  notebooks
};

const catalog_collator = new Intl.Collator("es", { numeric: true, sensitivity: "base" });
const catalog_sort = (a, b) => catalog_collator.compare(a.deviceType, b.deviceType) || catalog_collator.compare(a.brand, b.brand) || catalog_collator.compare(a.model, b.model) || (a.memory.storageGb ?? 0) - (b.memory.storageGb ?? 0) || (a.memory.ramGb ?? 0) - (b.memory.ramGb ?? 0);
const groupBy = (items, field) => items.reduce((groups, item) => { (groups[item[field]] ??= []).push(item); return groups; }, {});

export const all_products = Object.values(catalog_by_category).flat().sort(catalog_sort);
export const catalog_by_device_type = groupBy(all_products, "deviceType");
export const catalog_by_brand = groupBy(all_products, "brand");
